4	// Points carry their exact formatted amount from the server; `y` is only used for pixel scale.
5	export type NetWorthPoint = { date: string; label: string; amount: string; y: number };
6	
7	const WIDTH = 640, HEIGHT = 140, PAD = 6;
8	
9	/** Net worth over time; hovering (or tapping) shows the exact amount and date at that point. */
10	export function NetWorthChart({ points, label }: { points: NetWorthPoint[]; label: string }) {
11	  const [active, setActive] = useState<number | null>(null);
12	  const gradient = useId();
13	  const values = points.map(point => point.y);
14	  const min = Math.min(...values), max = Math.max(...values), span = max - min || 1;
15	  const x = (index: number) => points.length === 1 ? WIDTH / 2 : (index / (points.length - 1)) * WIDTH;
16	  const y = (value: number) => HEIGHT - PAD - ((value - min) / span) * (HEIGHT - PAD * 2);
17	  const line = points.map((point, index) => `${x(index).toFixed(1)},${y(point.y).toFixed(1)}`).join(" ");
18	  const pick = (clientX: number, rect: DOMRect) => setActive(Math.max(0, Math.min(points.length - 1, Math.round(((clientX - rect.left) / rect.width) * (points.length - 1)))));
19	  const shown = active === null ? null : points[active];
20	  return <div className="relative" onPointerLeave={() => setActive(null)}>
21	    <svg role="img" aria-label={label} viewBox={`0 0 ${WIDTH} ${HEIGHT}`} preserveAspectRatio="none" className="h-[140px] w-full cursor-crosshair touch-none overflow-visible text-brand"
22	      onPointerMove={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())} onPointerDown={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())}>
23	      <defs><linearGradient id={gradient} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity={0.22} /><stop offset="100%" stopColor="currentColor" stopOpacity={0} /></linearGradient></defs>
24	      <polygon points={`0,${HEIGHT} ${line} ${WIDTH},${HEIGHT}`} fill={`url(#${gradient})`} />
25	      <polyline points={line} fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
26	      {active !== null && <line x1={x(active)} x2={x(active)} y1={0} y2={HEIGHT} stroke="var(--color-muted-foreground)" strokeOpacity={0.5} strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />}
27	    </svg>
28	    {shown && <>
29	      <span aria-hidden="true" className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-card bg-brand shadow"
30	        style={{ left: `${(x(active!) / WIDTH) * 100}%`, top: `${(y(shown.y) / HEIGHT) * 100}%` }} />
31	      <div role="status" className="pointer-events-none absolute z-10 rounded-lg border border-border bg-card px-3 py-2 shadow-lg"
32	        style={{ left: `clamp(0px, calc(${(x(active!) / WIDTH) * 100}% - 4.5rem), calc(100% - 9rem))`, top: `max(0px, calc(${(y(shown.y) / HEIGHT) * 100}% - 4.75rem))` }}>
33	        <p className="whitespace-nowrap font-mono text-sm font-semibold">{shown.amount}</p>
34	        <p className="whitespace-nowrap text-[11px] text-muted-foreground">{shown.label}</p>
35	      </div>
36	    </>}
37	  </div>;
38	}
