1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { calendarDate } from "@/lib/finance/calendar";
3	import type { WealthItem } from "@/lib/finance/wealth";
4	
5	type Snapshot = { account_id: string; amount_minor: string | number; currency_code: string; as_of: string; undone_at?: string | null };
6	type Valuation = { item_id: string; created_at: string; kind: string; amount_minor: string; currency_code: string; as_of: string; linked_account_id: string | null };
7	type Posting = { account_id: string; amount_minor: string | number; currency_code: string; posted_on: string; status: string };
8	type NetWorthPoint = { date: string; accounts: Map<string, bigint>; assets: Map<string, bigint>; debts: Map<string, bigint>; known: boolean };
9	
10	const add = (map: Map<string, bigint>, currency: string, amount: bigint) => map.set(currency, (map.get(currency) ?? 0n) + amount);
11	
12	// Month ends for the last `months` months, then today.
13	export function monthEnds(today: string, months: number): string[] {
14	  const [year, month] = today.split("-").map(Number);
15	  const dates = Array.from({ length: months }, (_, index) => new Date(Date.UTC(year, month - 1 - (months - 1 - index), 0)).toISOString().slice(0, 10));
16	  return [...dates, today];
17	}
18	
19	// Recorded net worth on each date: the latest recorded account balance and the latest standalone
20	// valuation dated on or before it. No FX and no interpolation; values carry forward until re-recorded.
21	// With a ledger, a date before an account's first recorded balance is worked back from that balance by
22	// removing the posted transactions after the date, but only from the day before its first posting, since
23	// earlier activity is not on record. `known` is false when nothing covers the date.
24	// ponytail: archived accounts are left out (matching Home); include them if history must show closed accounts.
25	export function netWorthSeries({ dates, timeZone, accountIds, snapshots, valuations, removedOn, ledger = [] }: {
26	  dates: string[]; timeZone: string; accountIds: Set<string>; snapshots: Snapshot[]; valuations: Valuation[]; removedOn: Map<string, string>; ledger?: Posting[];
27	}): NetWorthPoint[] {
28	  const balances = snapshots.filter(row => !row.undone_at && accountIds.has(row.account_id))
29	    .map(row => ({ key: row.account_id, date: calendarDate(row.as_of, timeZone), at: row.as_of, amount: BigInt(row.amount_minor), currency: row.currency_code }));
30	  const values = valuations.filter(row => !row.linked_account_id)
31	    .map(row => ({ key: row.item_id, date: row.as_of, at: row.created_at, amount: BigInt(row.amount_minor), currency: row.currency_code, debt: row.kind === "debt" }));
32	  const latest = <T extends { key: string; date: string; at: string }>(rows: T[], date: string) => {
33	    const pick = new Map<string, T>();
34	    for (const row of rows) {
35	      if (row.date > date) continue;
36	      const prior = pick.get(row.key);
37	      if (!prior || row.date > prior.date || (row.date === prior.date && row.at >= prior.at)) pick.set(row.key, row);
38	    }
39	    return pick.values();
40	  };
41	  const posted = ledger.filter(row => row.status === "posted" && accountIds.has(row.account_id));
42	  const firstPosted = new Map<string, string>();
43	  for (const row of posted) if (!firstPosted.has(row.account_id) || row.posted_on < firstPosted.get(row.account_id)!) firstPosted.set(row.account_id, row.posted_on);
44	  const dayBefore = (date: string) => new Date(Date.parse(`${date}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
45	  return dates.map(date => {
46	    const point: NetWorthPoint = { date, accounts: new Map(), assets: new Map(), debts: new Map(), known: false };
47	    const recorded = [...latest(balances, date)];
48	    for (const row of recorded) add(point.accounts, row.currency, row.amount);
49	    for (const key of accountIds) {
50	      const first = firstPosted.get(key);
51	      if (recorded.some(row => row.key === key) || !first || date < dayBefore(first)) continue;
52	      const next = balances.filter(row => row.key === key && row.date > date).sort((a, b) => a.date.localeCompare(b.date) || a.at.localeCompare(b.at))[0];
53	      if (!next) continue;
54	      const after = posted.filter(row => row.account_id === key && row.currency_code === next.currency && row.posted_on > date && row.posted_on <= next.date)
55	        .reduce((sum, row) => sum + BigInt(row.amount_minor), 0n);
56	      add(point.accounts, next.currency, next.amount - after);
57	    }
58	    for (const row of latest(values, date)) {
59	      const removed = removedOn.get(row.key);
60	      if (removed && removed <= date) continue;
61	      add(row.debt ? point.debts : point.assets, row.currency, row.amount);
62	    }
63	    point.known = point.accounts.size + point.assets.size + point.debts.size > 0;
64	    return point;
65	  });
66	}
