68	export function netWorth(point: NetWorthPoint): Map<string, bigint> {
69	  const total = new Map<string, bigint>();
70	  for (const map of [point.accounts, point.assets, point.debts]) for (const [currency, amount] of map) add(total, currency, amount);
71	  return total;
72	}
