74	type WealthEvent = { id: string; item_id: string; before: WealthItem | null; after: WealthItem; created_at: string; undone_at: string | null };
75	
76	/** Every saved valuation event (newest first), paged; the Wealth page lists them and both it and Home chart them. */
77	export async function loadWealthEvents(db: SupabaseClient, workspaceId: string): Promise<WealthEvent[]> {
78	  const rows: WealthEvent[] = [];
79	  for (let offset = 0; ; offset += 1000) {
80	    const { data, error } = await db.from("wealth_events").select("id, item_id, before, after, created_at, undone_at").eq("workspace_id", workspaceId)
81	      .order("created_at", { ascending: false }).order("id").range(offset, offset + 999);
82	    if (error) throw error;
83	    rows.push(...(data ?? []) as WealthEvent[]);
84	    if (!data || data.length < 1000) return rows;
85	  }
86	}
87	
88	// Valuation history = every non-undone saved version of each item, plus the current row.
89	export function valuationHistory(events: WealthEvent[], items: WealthItem[]): Valuation[] {
90	  return [...events.filter(event => !event.undone_at && !event.after.removed_at).map(event => ({ ...event.after, item_id: event.item_id, created_at: event.created_at, amount_minor: String(event.after.amount_minor) })),
91	    ...items.map(item => ({ ...item, item_id: item.id, created_at: "9999-12-31" }))];
92	}
93	
94	export const removedOn = (items: WealthItem[], timeZone: string) => new Map(items.filter(item => item.removed_at).map(item => [item.id, calendarDate(item.removed_at!, timeZone)]));
